'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages=[['overview','◈','工作台'],['projects','▦','项目空间'],['context','▤','产品上下文'],['missions','◎','测试任务'],['execution','▷','执行中心'],['assessment','◇','交付评估'],['capabilities','⊞','能力与集成']];
const aliases={runs:'execution',connect:'projects',documents:'context',rules:'context',cases:'missions',report:'assessment',environment:'projects',settings:'capabilities'};
const sources=[{path:'docs/product-prd.md',kind:'产品需求',role:'业务依据候选',text:'已完成支付的订阅订单，在适用退款窗口内可以申请退款。每次操作必须有明确的权限和审计记录。',checked:true},{path:'docs/refunds.md',kind:'业务补充',role:'业务依据候选',text:'退款窗口为付款后 14 天。同一幂等键的重复退款请求，只能产生一次退款。',checked:true},{path:'api/openapi.yaml',kind:'接口契约',role:'结构与状态码约束',text:'POST /refunds：要求 Idempotency-Key 请求头；成功返回 refundId。',checked:true},{path:'README.md',kind:'运行说明',role:'启动与环境信息',text:'使用测试环境运行服务。历史说明：退款窗口为付款后 7 天。此条与业务补充冲突，需要负责人确认。',checked:true},{path:'tests/refund.spec.ts',kind:'已有测试',role:'实现线索，不自动作业务依据',text:'现有测试覆盖订阅购买和退款成功路径。未包含重复提交的业务断言。',checked:true}];
const templates={release:['◉','发布验收','核对业务承诺与交付结果'],regression:['↗','变更回归','聚焦变更，再覆盖核心链路'],health:['⌁','项目体检','发现可用性与基础质量问题'],retest:['↻','缺陷复测','用同一依据验证新的版本']};
const channels={web:{name:'浏览器业务链路',count:8,pass:7,fail:0,blocked:1,notrun:0,sub:'双角色 · Chromium · 关键页面与权限'},api:{name:'API 业务契约',count:4,pass:3,fail:1,blocked:0,notrun:0,sub:'接口与状态 · 幂等性 · 业务结果'},existing:{name:'仓库已有测试',count:10,pass:9,fail:0,blocked:0,notrun:1,sub:'受控执行 · 独立标记覆盖范围'}};
let state,timer,toastTimer;
function initial(){return {connected:false,source:'git',repo:'https://github.com/example/subscription-cloud',ref:'main',url:'https://staging.example.com',chosen:sources.map((s,i)=>i),decision:'',rationale:'',snapshot:1,template:'release',goal:'验收本次订阅升级与退款链路，检查跨角色权限和重复提交。',budget:10,plan:false,selected:['web','api','existing'],run:null,runNumber:0,retest:false};}
function reset(){clearInterval(timer);state=initial();}
reset();
const pill=(t,c='')=>`<span class="pill ${c}">${t}</span>`;
const btn=(t,a,c='',extra='')=>`<button class="btn ${c}" data-action="${a}" ${extra}>${t}</button>`;
const navbtn=(t,r,c='')=>`<a class="btn ${c}" href="#${r}">${t}</a>`;
const head=(label,title,desc,action='')=>`<div class="page-heading"><div><div class="eyebrow">${label}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${action}</div></div>`;
const panel=(title,body,extra='',desc='')=>`<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${extra}</div><div class="panel-body">${body}</div></section>`;
const stat=(label,value,sub)=>`<div class="stat"><div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-sub">${sub}</div></div>`;
function route(){const r=location.hash.slice(1);return aliases[r]||((pages.some(p=>p[0]===r))?r:'overview');}
function go(r){if(route()===r){render();}else{location.hash=r;}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function modal(title,body,foot=''){ $('#dialog-content').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="close" data-action="close" aria-label="关闭">×</button></div><div class="dialog-body">${body}</div>${foot?`<div class="dialog-foot">${foot}</div>`:''}`;if(!$('#detail').open)$('#detail').showModal();}
function close(){ $('#detail').close();}
function overview(){return head('QUALITY WORKSPACE','让每次交付，都有依据。','从项目与需求出发，直到可复现的交付结论。',btn('＋ 接入项目','connect')+navbtn('新建测试任务 ↗','missions','primary'))+`<section class="hero"><div><div class="eyebrow">FROM INTENT TO EVIDENCE</div><h2>描述你要验证的目标。<br>让测试沿着业务发生。</h2><p>自动发现项目资料，形成测试方案，协调多种执行能力。<br>你掌握关键判断，平台组织验证与证据。</p>${navbtn('开始一次交付验收 →','missions')}</div><div class="hero-art"><div class="trace"><span>项目与需求</span><span>→</span><span>测试任务</span><span>→</span><b>交付结论</b></div><div class="signal"><i>✳</i><div><strong>每一个判断，都能回到来源。</strong><small>需求片段 → 可观察断言 → 执行证据</small></div></div></div></section><div class="stats">${stat('示例项目','3','跨业务领域，共用一套验收流程')}${stat('本次需验收的检查','22','浏览器 8 · API 4 · 已有测试 10')}${stat('需要人的判断',state.decision?'1':'2',state.decision?'补齐财务角色测试账号':'确认规则冲突 · 补齐测试账号')}${stat('已有评估中的问题','1','重复退款 · 示例历史评估')}</div><div class="grid-2">${panel('项目与最近交付',`<div class="row"><div class="row-left"><span class="project-icon">S</span><div class="row-main"><strong>Subscription Cloud</strong><p>订阅管理 · Web / API · v0.9.0</p></div></div>${pill('待交付评估','amber')}${navbtn('进入项目','projects','small')}</div><div class="row"><div class="row-left"><span class="project-icon green">R</span><div class="row-main"><strong>Retail Operations</strong><p>零售订单 · Web · v2.4.1</p></div></div>${pill('尚未验收')}</div><div class="row"><div class="row-left"><span class="project-icon orange">A</span><div class="row-main"><strong>Atlas API</strong><p>开发者服务 · API · v1.3.0</p></div></div>${pill('尚未验收')}</div>`,pill('示例空间'))}${panel('优先处理',`<div class="row"><div class="row-main"><strong>${state.decision?'退款窗口已确认':'退款窗口存在两个版本'}</strong><p>${state.decision?'依据与决策已记录到当前上下文':'README：7 天 / 产品补充：14 天'}</p></div>${navbtn(state.decision?'查看':'确认','context','small')}</div><div class="row"><div class="row-main"><strong>财务角色缺少测试账号</strong><p>影响 1 项业务检查，结论将保留缺口。</p></div>${btn('查看','account','small')}</div><div class="row"><div class="row-main"><strong>重复退款需要复现</strong><p>查看期望、实际结果与请求证据。</p></div>${btn('查看示例','sample','small')}</div>`)} </div>${panel('四种目标，一条工作流',`<div class="template-grid" style="margin-bottom:0">${Object.entries(templates).map(([k,v])=>`<button class="template" data-action="choose-template" data-template="${k}"><span class="symbol">${v[0]}</span><strong>${v[1]}</strong><small>${v[2]}</small></button>`).join('')}</div>`)}`;}
function projects(){return head('PROJECTS','一次接入，持续理解。','仓库、运行环境和资料共同构成项目，无需重复上传仓库中已有的 PRD。',btn('＋ 接入项目','connect','primary'))+`<div class="project-cards">${[['S','Subscription Cloud','订阅升级、退款与角色权限','Web + API',''],['R','Retail Operations','零售订单、库存与履约','Web','green'],['A','Atlas API','开发者服务、鉴权与配额','API','orange']].map(([i,n,d,t,c],idx)=>`<div class="project-card"><div class="actions"><span class="project-icon ${c}">${i}</span>${pill(idx===0&&state.connected?'已接入（演示）':'示例项目',idx===0&&state.connected?'green':'')}</div><h2>${n}</h2><p>${d}</p><div class="tagline">${pill(t)}${pill(idx===0?'1 项目上下文':'未配置上下文')}</div><div class="project-meta"><span>${idx===0?'最近版本 v0.9.0':'等待首次验收'}</span>${idx===0?navbtn('管理上下文 →','context','small'):btn('使用此类场景','scenario','small',`data-name="${n}"`)}</div></div>`).join('')}</div><div class="grid-2">${panel('Subscription Cloud · 接入信息',`<div class="row"><div class="row-main"><strong>${state.source==='git'?'Git 仓库':state.source==='url'?'已有环境':'自托管执行器'}</strong><p class="file-name">${esc(state.source==='git'?state.repo:state.source==='url'?state.url:'团队控制的执行环境')}</p></div>${pill(state.connected?'本地演示已配置':'待配置',state.connected?'blue':'')}</div><div class="row"><div class="row-main"><strong>目标版本与运行环境</strong><p>ref：${esc(state.ref)} · 演示快照 demo-a31c9e2 · staging</p></div>${pill('运行构建未核验','amber')}</div><div class="row"><div class="row-main"><strong>资料自动发现</strong><p>PRD、业务说明、接口契约和已有测试统一进入上下文。</p></div>${navbtn('查看资料','context','small')}</div>`,btn('配置接入','connect','small'))}${panel('选择适合你的接入方式',`<div class="row"><div class="row-main"><strong>连接 Git 仓库</strong><p>发现资料与测试。受控构建是独立能力，不能保证任意仓库直接运行。</p></div></div><div class="row"><div class="row-main"><strong>连接已有测试环境</strong><p>通过 URL 和账号测试业务；被测系统可以使用任意后端语言。</p></div></div><div class="row"><div class="row-main"><strong>使用自己的执行器</strong><p>在内网运行或复用已有工具，结果按统一协议回传。1.0 目标能力。</p></div></div>`)} </div>`;}
function context(){return head('PRODUCT CONTEXT','把资料变成可靠的测试依据。','发现文件只是开始：保留来源，明确适用版本，把歧义交给有权决定的人。',btn('补充资料','upload')+btn(state.connected?'重新选择资料':'连接仓库并发现','connect','primary'))+`<div class="notice">${state.connected?`当前演示快照 CONTEXT-${state.snapshot} · ${state.chosen.length} 项来源已纳入。`:'下方为完整示例上下文；连接流程可演示仓库资料的发现与选择。'} 实现代码和已有测试作为线索，不自动成为业务真值。</div><div class="grid-2">${panel('资料与来源',`<div class="table-wrap"><table><thead><tr><th>文件 / 来源</th><th>用途</th><th></th></tr></thead><tbody>${sources.map((s,i)=>`<tr><td><strong class="file-name">${esc(s.path)}</strong><small>${s.kind} · demo-a31c9e2</small></td><td>${pill(s.role,i<2?'blue':'')} ${state.connected&&!state.chosen.includes(i)?pill('未纳入'):''}</td><td>${btn('详情','source','small',`data-index="${i}"`)}</td></tr>`).join('')}</tbody></table></div>`,pill('来源可追溯'))}${panel('需要确认的业务决策',state.decision?`<div class="notice green">退款窗口已确认：${state.decision==='14'?'14':'7'} 天。</div><h3>决策依据</h3><p class="description" style="margin-top:9px">${esc(state.rationale)}</p><div class="decision">负责人：李博闻（演示）<br>关联来源：${state.decision==='14'?'docs/refunds.md':'README.md'}<br>当前快照：CONTEXT-${state.snapshot}</div><p class="tiny muted" style="margin-top:15px">后续资料变更须形成新快照。已执行任务继续保留原依据。</p>`:`<div class="actions" style="margin-bottom:14px">${pill('冲突','amber')}${pill('影响退款边界检查')}</div><h3>退款窗口是 7 天还是 14 天？</h3><p class="description" style="margin-top:10px">README 写明 7 天，业务补充写明 14 天。模型不能自行判断哪个版本有效。</p><div class="decision">其余已明确条款可进入方案；受影响的业务断言在确认前不得通过。</div><div style="margin-top:20px">${btn('确认适用规则','resolve','primary')}</div>`)} </div>${panel('已提取的业务规则（示例）',`<div class="journey"><span class="number">01</span><div><strong>同一幂等键最多触发一次退款</strong><p>docs/refunds.md §2 → 退款重复提交断言</p></div>${pill('已确认','green')}</div><div class="journey"><span class="number">02</span><div><strong>财务操作必须限制在授权角色内</strong><p>docs/product-prd.md §4 → 双角色权限断言</p></div>${pill('已确认','green')}</div><div class="journey"><span class="number">03</span><div><strong>退款申请时间窗口${state.decision?'：'+state.decision+' 天':''}</strong><p>docs/refunds.md ↔ README.md → 边界断言</p></div>${pill(state.decision?'已确认':'待确认',state.decision?'green':'amber')}</div>`,btn('演示资料变更','sync','small'))}`;}
function missions(){const v=templates[state.template];return head('TEST MISSIONS','从一个目标，组织一次验证。','按业务目标选择模板。平台组织依据、测试范围、执行能力和证据。',state.plan?btn('重新整理方案','prepare'):'')+`<div class="template-grid">${Object.entries(templates).map(([k,t])=>`<button class="template ${state.template===k?'selected':''}" data-action="choose-template" data-template="${k}" aria-pressed="${state.template===k}"><span class="symbol">${t[0]}</span><strong>${t[1]}</strong><small>${t[2]}</small></button>`).join('')}</div><div class="grid-2">${panel(v[1]+' · Subscription Cloud',`<label class="field"><span>本次希望验证什么？</span><textarea id="goal" data-field="goal">${esc(state.goal)}</textarea></label><div class="grid-equal" style="gap:15px"><label class="field"><span>目标版本</span><input value="v0.9.0 · demo-a31c9e2" readonly><small>演示版本；真实执行须固定构建与来源。</small></label><label class="field"><span>执行预算</span><select data-field="budget" id="budget">${[5,10,20].map(n=>`<option value="${n}" ${state.budget===n?'selected':''}>最多 ${n} 分钟</option>`).join('')}</select><small>预算耗尽保留未完成项，不自动补成通过。</small></label></div><div class="actions">${btn(state.plan?'更新测试方案':'生成测试方案（演示）','prepare','primary')}${pill('staging 测试环境')}</div>`,pill('目标驱动','blue'))}${panel('自动组织什么',`<div class="row"><div class="row-main"><strong>理解项目与相关需求</strong><p>使用已纳入的资料快照；缺少依据时明确列出。</p></div><span class="muted">01</span></div><div class="row"><div class="row-main"><strong>安排可执行的检查</strong><p>浏览器、API 与已有测试分工，选择有能力完成的任务。</p></div><span class="muted">02</span></div><div class="row"><div class="row-main"><strong>保留完整的评估边界</strong><p>哪些验证过，哪些被阻塞，哪些仍不能判断。</p></div><span class="muted">03</span></div>`)}</div>${state.plan?plan():''}`;}
function plan(){const health=state.template==='health';return panel('测试方案 · 待执行',`<div class="notice ${health?'':'amber'}">${health?'项目体检仅评估示例环境可用性，不代表业务正确。':!state.decision?'退款窗口冲突尚未确认。请先完成业务决策，再执行这份业务验收方案。':'1 项缺少财务角色账号；1 项已有测试尚未配置执行条件。将保留在评估范围内，不能视为通过。'}</div><div class="grid-equal"><div><h3>验收范围</h3>${health?`<div class="journey"><span class="number">01</span><div><strong>页面可访问与基础健康</strong><p>HTTP 响应 / 页面加载 / 基础错误信号</p></div>${pill('2 项')}</div>`:`<div class="journey"><span class="number">01</span><div><strong>订阅升级与支付结果</strong><p>业务结果与界面状态一致</p></div>${pill('核心链路')}</div><div class="journey"><span class="number">02</span><div><strong>退款边界与重复提交</strong><p>有来源的边界值与接口业务断言</p></div>${pill('高风险','amber')}</div><div class="journey"><span class="number">03</span><div><strong>财务角色与权限隔离</strong><p>明确测试账号和跨角色前置条件</p></div>${pill('缺账号','amber')}</div>`}</div><div><h3>执行能力</h3>${health?`<label class="checkbox"><input type="checkbox" checked disabled><span><strong>浏览器基础健康检查 · 2 项</strong><small>无业务真值推断</small></span></label>`:Object.entries(channels).map(([k,c])=>`<label class="checkbox"><input type="checkbox" data-channel="${k}" ${state.selected.includes(k)?'checked':''}><span><strong>${c.name} · ${c.count} 项</strong><small>${c.sub}</small></span></label>`).join('')}<p class="tiny muted">此处演示跨执行能力编排。API 与已有测试接入属于 1.0 目标，当前主程序尚未具备。</p></div></div><div class="decision">${health?'体检方案':'验收基线'}包含 ${health?2:22} 项检查 · 预算 ${state.budget} 分钟 · ${state.connected?'CONTEXT-'+state.snapshot:'示例上下文'}。<br>关闭执行能力会保留对应的未执行缺口，不缩小验收分母。环境构建身份未核验，会限制最终结论。</div><div class="actions" style="margin-top:20px">${btn('确认方案并开始演示','start','primary',!health&&!state.decision?'disabled':'')}${!health&&!state.decision?navbtn('先确认规则 →','context'):''}<small>只在本地模拟进度，不调用服务，不产生费用。</small></div>`);}
function execution(){let r=state.run;return head('EXECUTION','看清正在发生的验证。','任务、执行能力与证据汇聚到同一次运行；取消和故障保留真实状态。',navbtn('新建测试任务','missions'))+(!r?panel('当前运行',`<div class="empty"><div class="empty-icon">▷</div><h2>等待一次有明确目标的测试</h2><p>从任务生成方案，确认必要的业务决策与测试范围，再开始执行。</p>${navbtn('创建测试任务','missions','primary')}</div>`):`<div class="notice">演示运行 ${r.id} · ${templates[r.template][1]} · 固定上下文 ${r.snapshot} · v0.9.0 · 预算 ${r.budget} 分钟。所有过程与证据均为本地示例。</div><div class="grid-2">${panel(esc(r.goal),`<div class="plan-header">${pill(r.status==='running'?'执行中':r.status==='cancelled'?'已取消':'已完成',r.status==='running'?'blue':'')}<span class="tiny muted">${r.status==='done'?'100':Math.min(100,r.step*20)}%</span></div><div class="progress"><div style="width:${r.status==='done'?100:r.step*20}%"></div></div><div class="phase-list">${['固定方案','准备环境','分配执行','收集证据','聚合结论'].map((t,i)=>`<span class="${i<=r.step?'active':''}">${i+1}. ${t}</span>`).join('')}</div><div style="margin-top:25px">${(r.template==='health'?['web']:r.channels).map((k,i)=>`<div class="lane"><div class="lane-header"><h3>${channels[k].name}</h3>${pill(r.status==='cancelled'?'已停止':r.status==='done'?'已收集示例结果':r.step<2?'等待中':'执行中',r.status==='running'&&r.step>=2?'blue':'')}</div><p>${r.template==='health'?'2 项基础健康检查':channels[k].sub}</p><div class="progress"><div style="width:${r.status==='done'?100:Math.max(0,Math.min(90,r.step*22-i*9))}%"></div></div></div>`).join('')}</div><div class="actions" style="margin-top:23px">${r.status==='running'?btn('取消本次演示','cancel','danger'):navbtn('查看本次评估 →','assessment','primary')}</div>`,pill(r.id))}${panel('过程记录',`<div class="logline"><span>00:00</span>冻结任务范围和资料快照</div>${r.step>=1?'<div class="logline"><span>00:01</span>准备示例账号与执行能力</div>':''}${r.step>=2?'<div class="logline"><span>00:02</span>逐项收集观察结果</div>':''}${r.step>=3?'<div class="logline"><span>00:03</span>检查断言与证据关联</div>':''}${r.status==='done'?'<div class="logline"><span>00:05</span>形成评估，保留所有缺口</div>':''}${r.status==='cancelled'?'<div class="logline"><span>停止</span>演示已取消，未产出项保留为未执行</div>':''}<p class="tiny muted" style="margin-top:20px">这里只展示模拟事件。真实平台需要心跳、租约、恢复与证据校验。</p>`)}</div>`)+panel('历史评估示例',`<div class="row"><div class="row-main"><strong>v0.8.9 · 退款与权限验收</strong><p>22 项检查 · 1 项失败 · 2 项缺口</p></div>${pill('FAIL','red')}${btn('打开示例报告','sample','small')}</div>`);}
function results(r){if(r.template==='health')return {total:2,pass:r.status==='done'?2:0,fail:0,blocked:0,notrun:r.status==='done'?0:2};let n={total:22,pass:0,fail:0,blocked:0,notrun:0};for(const[k,c]of Object.entries(channels)){if(r.status!=='done'||!r.channels.includes(k))n.notrun+=c.count;else for(const v of ['pass','fail','blocked','notrun'])n[v]+=c[v];}return n;}
function assessment(){const r=state.run;if(!r||r.status==='running')return head('DELIVERY ASSESSMENT','用证据，回答能否交付。','结论严格对应本次范围；执行完成不等于业务通过。')+panel('当前交付评估',`<div class="empty"><div class="empty-icon">◇</div><h2>${r?'本次运行尚未完成':'还没有本次评估'}</h2><p>可先浏览一份明确标记的历史示例，或创建测试任务体验完整流程。</p><div class="actions" style="justify-content:center">${btn('浏览历史示例','sample')}${navbtn(r?'返回执行中心':'创建测试任务',r?'execution':'missions','primary')}</div></div>`);return report(r,false);}
function report(r,sample){const n=results(r),health=r.template==='health',fail=n.fail>0,title=fail?'发现阻断交付的问题':health&&r.status==='done'?'基础健康检查通过，业务尚未验收':'验收不完整，暂不能确认交付',verdict=fail?'FAIL':health&&r.status==='done'?'HEALTH PASS':'INCOMPLETE';return head('DELIVERY ASSESSMENT',sample?'历史评估示例':'本次交付评估',`${esc(r.id)} · ${templates[r.template][1]} · v0.9.0 · ${sample?'纯示例，非真实执行':'本地模拟结果'}`,btn('导出评估 JSON',sample?'export-sample':'export')+btn('记录交付决定','release-decision'))+`<div class="verdict"><span class="verdict-icon">${fail?'!':'◇'}</span><div><h2>${title}</h2><p>${fail?'重复请求产生了两笔退款。另有未完成检查和构建身份缺口。':health?'2 项体检结果仅说明基础可用性，不能推断业务规则被满足。':'被取消、未选能力、缺失条件与未核验构建均保留为缺口。'}</p></div>${pill(verdict,fail?'red':'amber')}</div><div class="stats">${stat('验收范围',String(n.total),'范围固定，未执行也计入')}${stat('通过',String(n.pass),`通过率 ${(n.pass/n.total*100).toFixed(1)}%`)}${stat('失败',String(n.fail),'有明确期望与反证')}${stat('未完成',String(n.blocked+n.notrun),`阻塞 ${n.blocked} · 未执行 ${n.notrun}`)}</div><div class="notice">执行率 ${((n.pass+n.fail)/n.total*100).toFixed(1)}% = 已形成通过或失败结论 / 范围总数。运行构建：已声明，未核验。${sample?'这份报告使用固定样例。':`冻结的上下文：${esc(r.snapshot)}；后续规则变更不会改写本报告。`}</div><div class="grid-2">${fail?panel('DEF-001 · 重复请求触发两次退款',`<div class="actions">${pill('业务失败','red')}${pill('API · 幂等性')}${pill('待负责人确认')}</div><div class="subhead">测试依据</div><p class="description">docs/refunds.md §2：同一幂等键的重复退款请求，只能产生一次退款。</p><div class="grid-equal" style="gap:16px;margin:19px 0"><div><h3>期望</h3><p class="description">两次请求返回同一退款结果；仅产生一笔 ¥99.00 的退款。</p></div><div><h3>实际（示例）</h3><p class="description">出现两个退款记录，累计退款 ¥198.00。</p></div></div><div class="evidence"><div class="evidence-head">证据示意 · 非真实请求 / 非真实运行截图</div><div class="evidence-body"><code>Idempotency-Key: refund-demo-001</code><div class="receipt">POST /refunds → refund_001 · ¥99.00</div><div class="receipt">POST /refunds → refund_002 · ¥99.00</div></div></div><div class="decision">观察事实：重复退款记录。<br>待验证假设：幂等校验可能未覆盖并发或写入过程；尚不能据此断定根因。</div><div class="actions" style="margin-top:19px">${btn('查看复现步骤','reproduce')}${btn(state.retest?'已建立复测草稿':'创建缺陷复测','retest','primary')}</div>`):panel('检查结果',`<div class="empty"><h2>${health&&r.status==='done'?'2 项基础健康检查完成':'没有足够证据形成完整业务结论'}</h2><p>未发现已执行检查失败，也不等于整个交付符合需求。缺口会保留在报告中。</p></div>`)}${panel('还不能确认什么',`<div class="row"><div class="row-main"><strong>构建身份未核验</strong><p>已声明 demo-a31c9e2；未证明当前环境运行的就是此构建。</p></div>${pill('REVIEW','amber')}</div>${n.blocked?`<div class="row"><div class="row-main"><strong>财务角色检查被阻塞</strong><p>缺少测试账号与角色权限。</p></div>${pill('BLOCKED','amber')}</div>`:''}${n.notrun?`<div class="row"><div class="row-main"><strong>${n.notrun} 项尚未执行</strong><p>${r.status==='cancelled'?'本次取消，没有完成的检查结果。':'包括未选能力或缺少执行条件的检查。'}</p></div>${pill('NOT RUN')}</div>`:''}<div class="decision">交付决定由负责人记录。接受风险不会把失败改成通过，也不会删除缺口。</div>`)} </div>`;}
function capabilities(){return head('CAPABILITIES & INTEGRATIONS','一种工作流，多种执行能力。','复用你的项目、工具和环境；每项能力使用统一的任务、预算与证据协议。',btn('了解自托管执行器','runner'))+`<div class="notice amber">下面是产品能力设计地图。主程序当前具备固定 Web 执行与部分文档 / 模型基础链路；原型中的跨能力编排不是已上线功能。</div>${panel('执行能力',`<div class="table-wrap"><table><thead><tr><th>能力</th><th>适用场景</th><th>当前代码</th><th>产品目标</th></tr></thead><tbody>${[['浏览器测试','Web 业务流程、多角色权限','固定用例已实现','1.0：通用绑定与执行'],['API 测试','接口契约、业务状态与幂等','未实现','1.0：注册接口与鉴权'],['Node / Python 已有测试','复用单测、集成测试和报告','未实现','1.0：受控命令与 JUnit 等报告'],['自托管执行器','内网、复杂依赖、多语言项目','未实现','1.0：接入与证据协议'],['AI 应用 / Agent 评测','数据集、评分器、重复评测','未实现','后续专项能力']].map(([a,b,c,d])=>`<tr><td><strong>${a}</strong></td><td>${b}</td><td>${pill(c,c.includes('已实现')?'green':'')}</td><td>${d}</td></tr>`).join('')}</tbody></table></div>`)}${panel('可配置的测试 Harness',`<p class="description" style="margin-bottom:19px">Harness 是组织模型、工具、执行和验收的运行框架。1.0 先提供可靠模板与节点协议，再开放可视化自由组装。</p><div class="harness">${[['发现','项目 / 文档 / 环境'],['理解','来源 / 规则 / 决策'],['计划','范围 / 断言 / 预算'],['执行','Web / API / 测试'],['核验','证据 / 缺口 / 结论']].map(([t,d],i)=>`<button data-action="node" data-index="${i}"><em>0${i+1}</em><strong>${t}</strong><small>${d}</small></button>`).join('')}</div><div class="flow"><span>统一输入输出</span><i>·</i><span>工具与权限范围</span><i>·</i><span>预算 / 取消 / 恢复</span><i>·</i><span>版本固定与证据校验</span></div>`,pill('点击节点查看设计','blue'))}<div class="grid-equal">${panel('模型是可替换能力',`<p class="description">文档理解、规则提取和测试规划由独立的 Python 智能层承担。保留统一结构校验、真实与模拟隔离，不让模型输出直接越过执行边界。</p><div class="actions" style="margin-top:16px">${pill('已有 Kimi 接入基础','green')}${pill('其他提供商：按适配与评测扩展')}</div>`)}${panel('接入已有研发流程',`<p class="description">Git / CI 触发回归，问题流转到团队系统，结果带着版本和证据回到交付流程。1.0 先实现最小可用协议，更多连接器按用户需求扩展。</p><div class="actions" style="margin-top:16px">${pill('Git 发现：1.0 目标')}${pill('CI / 问题同步：后续集成')}</div>`)}</div>`;}
function render(){const r=route();$('#navigation').innerHTML=pages.map(([id,icon,name])=>`<a href="#${id}" class="${r===id?'active':''}" ${r===id?'aria-current="page"':''}><span class="nav-icon">${icon}</span>${name}${id==='context'&&!state.decision?'<span class="count">1</span>':''}</a>`).join('');$('#breadcrumb').textContent=pages.find(p=>p[0]===r)[2];$('#content').innerHTML=({overview,projects,context,missions,execution,assessment,capabilities}[r])();}
function intake(){modal('接入一个项目',`<p>连接后统一发现项目中的资料、测试与运行线索。以下操作只模拟流程。</p><div class="tabs">${[['git','Git 仓库'],['url','已有测试环境'],['runner','自托管执行器']].map(([k,t])=>`<button data-action="intake-mode" data-mode="${k}" class="${state.source===k?'selected':''}">${t}</button>`).join('')}</div>${state.source==='git'?`<label class="field"><span>GitHub 仓库地址</span><input id="repo" value="${esc(state.repo)}" placeholder="https://github.com/team/project"><small>演示仅接受标准 HTTPS 仓库地址，不包含凭据。</small></label><label class="field"><span>分支或标签</span><input id="ref" value="${esc(state.ref)}"></label>`:state.source==='url'?`<label class="field"><span>测试环境 URL</span><input id="environment-url" value="${esc(state.url)}" placeholder="https://staging.example.com"></label><div class="notice">语言不限制已有环境接入。仅有 URL 不能推导完整业务需求；下一步可补充产品资料。</div>`:`<div class="notice">自托管执行器是 1.0 目标能力，当前只展示设计。</div><p>用于内网、Python 或复杂多服务项目。平台下发签名任务和预算，执行器在授权范围内运行并回传证据。</p><div class="flow"><span>注册执行器</span><i>→</i><span>声明能力</span><i>→</i><span>领取受控任务</span></div>`}<div id="input-error" class="error" role="alert"></div>`,btn('取消','close')+(state.source==='runner'?btn('查看能力规划','runner-page','primary'):btn(state.source==='git'?'发现项目资料（演示）':'保存环境（演示）','discover','primary')));}
function validURL(raw,git=false){try{const u=new URL(raw);return u.protocol==='https:'&&!u.username&&!u.password&&!u.search&&!u.hash&&(!git||u.hostname==='github.com'&&/^\/[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+\/?$/.test(u.pathname));}catch{return false;}}
function discovery(){modal('已发现可用资料 · 演示',`<p>下列内容是固定演示数据，并非从你填写的仓库读取。资料各有用途，不会全部自动成为业务依据。</p><div class="notice">来源：${esc(state.repo)}<br>ref：${esc(state.ref)} · 快照：demo-a31c9e2</div>${sources.map((s,i)=>`<label class="checkbox source-item"><input type="checkbox" data-source="${i}" ${state.chosen.includes(i)?'checked':''}><span><strong class="file-name">${esc(s.path)}</strong><small>${s.kind} · ${s.role}</small></span></label>`).join('')}<div id="input-error" class="error" role="alert"></div>`,btn('返回','connect')+btn('纳入产品上下文','import','primary'));}
function sampleRun(){return {id:'DEMO-HISTORY-001',template:'release',status:'done',step:5,channels:['web','api','existing'],snapshot:'示例基线 / 14 天',goal:'订阅退款与权限验收',budget:10};}
function exportReport(sample){const r=sample?sampleRun():state.run;if(!r||r.status==='running')return;const n=results(r);const data={prototype:true,realExecution:false,run:r,results:n,buildVerified:false,verdict:n.fail?'FAIL':r.template==='health'&&r.status==='done'?'HEALTH_PASS':'INCOMPLETE',note:'演示结果不可用于真实发布决策'};const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='aiqa-demo-assessment.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('已导出带有“演示”标记的评估');}
function start(){if(!state.plan||state.run?.status==='running'){toast('已有运行正在执行，请先完成或取消');return;}if(state.template!=='health'&&!state.decision)return;if(state.template!=='health'&&!state.selected.length){toast('请至少选择一种执行能力');return;}const health=state.template==='health';state.run={id:'DEMO-RUN-'+String(++state.runNumber).padStart(3,'0'),goal:state.goal,template:state.template,channels:health?['web']:[...state.selected],budget:state.budget,snapshot:`CONTEXT-${state.snapshot} / ${state.decision||'无业务规则'} 天`,status:'running',step:0};clearInterval(timer);go('execution');timer=setInterval(()=>{if(state.run?.status!=='running'){clearInterval(timer);return;}state.run.step++;if(state.run.step>=5){state.run.status='done';clearInterval(timer);toast('演示完成，已保留失败和未完成项');}if(route()==='execution'||route()==='assessment')render();},1100);}
const actions={
reset(){reset();close();go('overview');toast('演示已重置');},close,connect:intake,
'intake-mode'(el){state.source=el.dataset.mode;intake();},
discover(){if(state.source==='git'){const repo=$('#repo').value.trim(),ref=$('#ref').value.trim();if(!validURL(repo,true)||!ref){$('#input-error').textContent='请输入不含凭据的 HTTPS GitHub 仓库地址，并填写版本。';return;}state.repo=repo;state.ref=ref;discovery();}else{const u=$('#environment-url').value.trim();if(!validURL(u)){$('#input-error').textContent='请输入不含凭据、参数或片段的 HTTPS 测试环境地址。';return;}state.url=u;state.connected=true;state.chosen=[];state.snapshot++;state.decision='';state.rationale='';state.plan=false;close();go('context');toast('环境已保存（演示）；请补充需求资料');}},
import(){const chosen=[...document.querySelectorAll('[data-source]:checked')].map(x=>Number(x.dataset.source));if(!chosen.length){$('#input-error').textContent='请至少选择一项资料。';return;}state.chosen=chosen;state.connected=true;state.snapshot++;state.decision='';state.rationale='';state.plan=false;close();go('context');toast('已建立演示上下文；业务冲突仍需确认');},
source(el){const s=sources[Number(el.dataset.index)];modal('来源详情',`<div class="actions" style="margin-bottom:18px">${pill(s.kind)}${pill(s.role,'blue')}</div><h3 class="file-name">${esc(s.path)}</h3><pre>${esc(s.text)}</pre><p>来源锚点：示例仓库 / demo-a31c9e2 / ${esc(s.path)}<br>内容摘要：demo-hash-${Number(el.dataset.index)+1}（演示值，非真实校验和）</p>`,btn('关闭','close'));},
resolve(){if(state.connected&&![1,3].every(i=>state.chosen.includes(i))){toast('此示例决策需要纳入 docs/refunds.md 与 README.md；请先选择资料');return;}modal('确认退款窗口',`<p>将选择记录为有来源的业务决策。已有运行仍引用原始快照。</p><label class="field"><span>当前版本适用的规则</span><select id="decision"><option value="14">14 天 · docs/refunds.md</option><option value="7">7 天 · README.md</option></select></label><label class="field"><span>决策说明（必填）</span><textarea id="rationale" placeholder="说明此来源为什么适用于当前版本"></textarea></label><div id="input-error" class="error" role="alert"></div>`,btn('取消','close')+btn('确认并记录','approve','primary'));},
approve(){let reason=$('#rationale').value.trim();if(!reason){$('#input-error').textContent='请填写业务决策说明。';return;}state.decision=$('#decision').value;state.rationale=reason;state.snapshot++;state.plan=false;close();render();toast('已记录依据，后续方案使用新的上下文快照');},
sync(){state.snapshot++;state.decision='';state.rationale='';state.plan=false;render();toast('已模拟来源变更：原有运行不变，新任务需重新确认规则');},
upload(){modal('补充项目资料',`<p>用于仓库中没有的 PRD、设计说明或补充约定。原型只显示文件名，不读取或上传内容。</p><label class="field"><span>选择文件</span><input id="document-file" type="file" accept=".md,.txt,.pdf,.docx,.png,.jpg,.jpeg"></label><div id="file-note" class="notice">尚未选择文件</div>`,btn('关闭','close'));},
'choose-template'(el){state.template=el.dataset.template;state.plan=false;state.goal={release:'验收本次订阅升级与退款链路，检查跨角色权限和重复提交。',regression:'回归退款接口的幂等性改动，并覆盖订阅升级与角色权限。',health:'检查测试环境是否可访问、页面能否加载以及基础错误信号。',retest:'在新版本中复测重复退款问题，保持原有业务期望不变。'}[state.template];go('missions');},
prepare(){if(!state.goal.trim()){toast('请填写测试目标');return;}state.plan=true;render();setTimeout(()=>document.querySelector('#content .panel:last-child')?.scrollIntoView({behavior:'smooth',block:'start'}),50);},start,
cancel(){if(state.run?.status!=='running')return;clearInterval(timer);state.run.status='cancelled';render();toast('演示已停止；未完成检查不会被计为通过');},
sample(){modal('历史评估 · 固定示例',`<p>这是独立于当前运行的固定示例，不代表正在执行任务的结果。</p><div class="notice red">FAIL · 22 项：19 通过、1 失败、1 阻塞、1 未执行。</div><h3>重复请求触发两次退款</h3><pre>依据：docs/refunds.md §2\n期望：同一幂等键最多一笔退款\n实际：两条退款记录，共 ¥198.00\n来源 / 构建 / 证据均为演示值</pre><p>通过率 86.4% · 执行率 90.9%。环境构建身份未核验。</p>`,btn('导出示例','export-sample')+btn('关闭','close','primary'));},
export(){exportReport(false);},'export-sample'(){exportReport(true);},
account(){modal('待补齐：财务角色测试账号',`<p>需要拥有财务审核权限的测试账号，验证未经授权的用户无法执行财务操作。</p><div class="notice amber">本原型不收集账号密码。真实产品使用项目凭据库，执行器按最小权限引用。</div><p>未提供账号时，对应检查保持 BLOCKED；其他检查可以独立执行。</p>`,btn('知道了','close','primary'));},
reproduce(){modal('复现步骤 · 示例',`<ol class="description"><li>准备一笔可退款、金额为 ¥99.00 的订阅订单。</li><li>以同一角色和幂等键发起退款请求。</li><li>再次提交相同请求，并核对退款记录。</li><li>断言仅有一笔退款；示例观察到两笔。</li></ol><div class="notice">请求使用测试环境和虚构数据；实际复现前需要明确夹具与环境权限。</div>`,btn('关闭','close'));},
retest(){state.retest=true;state.template='retest';state.goal='在新的目标构建中复测 DEF-001 重复退款问题；沿用原始幂等性断言。';state.plan=false;toast('已建立复测草稿；原报告继续保留 FAIL');render();},
'release-decision'(){modal('记录交付决定',`<p>交付决定与测试结论分别保留。接受风险不会改写失败或清除未完成检查。</p><label class="field"><span>负责人决定</span><select id="release-choice"><option>暂缓交付</option><option>接受已知风险后交付</option></select></label><label class="field"><span>理由与后续安排</span><textarea id="release-reason"></textarea></label><div id="input-error" class="error" role="alert"></div>`,btn('取消','close')+btn('记录（演示）','save-release','primary'));},
'save-release'(){if(!$('#release-reason').value.trim()){$('#input-error').textContent='请填写决定理由。';return;}if(state.run)state.run.deliveryDecision={choice:$('#release-choice').value,reason:$('#release-reason').value.trim()};close();toast('已记录在本次演示运行中；测试结论保持不变');},
runner(){modal('自托管执行器 · 设计',`<p>让运行留在团队控制的环境，平台负责下发任务、记录结果与形成评估。</p><div class="flow"><span>一次注册</span><i>→</i><span>领取任务</span><i>→</i><span>回传证据</span></div><div class="decision">统一要求：能力声明、凭据引用、作用域、租约、取消、预算、产物校验。<br>1.0 目标能力，当前尚未实现。</div>`,btn('关闭','close'));},
'runner-page'(){close();go('capabilities');},
node(el){const i=Number(el.dataset.index);const n=[['发现','输入：仓库引用、已有环境或上传资料。输出：带来源与版本的候选上下文。','只读访问；限制文件大小与数量；跳过密钥与不可访问文件。'],['理解','输入：候选上下文。输出：有来源的规则、冲突与缺失条件。','不把文档指令当作执行授权；业务决策由负责人确认。'],['计划','输入：目标、已确认规则和可用能力。输出：有界测试方案。','验收分母固定；缺条件显式阻塞；断言必须可观察。'],['执行','输入：固定计划、环境和凭据引用。输出：观察结果与原始产物。','受限网络、预算、租约、取消与隔离；重试不能覆盖历史。'],['核验','输入：断言、结果与证据。输出：缺陷、缺口与交付评估。','核对归属、校验和与完整性；无证据不能通过。']][i];modal(n[0]+'节点',`<p>${n[1]}</p><div class="notice">${n[2]}</div><p>每个节点记录模型 / 工具版本、输入输出摘要与失败原因。自由拖拽编排留到协议稳定之后。</p>`,btn('关闭','close'));},
scenario(el){modal(esc(el.dataset.name)+' · 通用场景',`<p>不同业务复用相同结构：项目 → 上下文 → 测试任务 → 执行 → 证据 → 交付评估。</p><p>当前完整可交互样例使用订阅业务；其他项目卡用于展示跨业务信息架构。</p>`,btn('关闭','close'));}
};
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled)actions[el.dataset.action]?.(el);});
document.addEventListener('input',e=>{if(e.target.dataset.field==='goal'){state.goal=e.target.value;state.plan=false;const startBtn=document.querySelector('[data-action="start"]');if(startBtn)startBtn.disabled=true;}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.field==='budget'){state.budget=Number(t.value);if(state.plan)render();}if(t.dataset.channel){state.selected=t.checked?[...new Set([...state.selected,t.dataset.channel])]:state.selected.filter(k=>k!==t.dataset.channel);}if(t.id==='document-file')$('#file-note').textContent=t.files.length?'已选择：'+t.files[0].name+'（仅显示名称，未上传）':'尚未选择文件';});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});render();
